using System;

namespace HRMS.Infrastructure.Services
{
    public static class KanrichLogoAsset
    {
        public const string LogoContentId = "kanrich_logo";
        public const string LogoMediaType = "image/png";
        public const string Base64Data = "";

        private static byte[]? _bytes;
        public static byte[] GetBytes()
        {
            return _bytes ??= Convert.FromBase64String(Base64Data);
        }
    }
}
